//! The IFC4 standard property sets a parameter named for one of their
//! properties is written in (RE-194, #817).
//!
//! Revit's exporter reads a project or shared parameter named
//! `<property set>.<property>`, such as `Pset_WallCommon.FireRating`, before
//! anything else for that property (`PropertySetEntry
//! ("Pset_WallCommon.FireRating", "FireRating")` in revit-ifc's property set
//! definitions, CLEANROOM.md source 5). [`STANDARD_PROPERTY_SETS`] is IFC4's
//! property sets that apply to an entity, generated by
//! `tools/ci/gen_standard_property_sets.py` from buildingSMART's own list of
//! IFC4's property set definitions, the one its validation service checks
//! rule PSE001 against (source 4), with IFC4's entity hierarchy, so that a
//! set applies to its entities' subtypes. A set scoped to a predefined type
//! applies to an element of that entity with that predefined type. Only the
//! single-value properties of the kinds a parameter's value is read as are
//! listed: booleans, text, counts and integers, lengths and thermal
//! transmittance.

mod table;

/// The value type IFC4 declares for a standard property.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[non_exhaustive]
pub enum StandardPropertyKind {
    /// `IfcBoolean`, from a Yes/No parameter.
    Boolean,
    /// `IfcIdentifier`, from a text parameter.
    Identifier,
    /// `IfcLabel`, from a text parameter.
    Label,
    /// `IfcText`, from a text parameter.
    Text,
    /// `IfcCountMeasure`, from an integer parameter.
    Count,
    /// `IfcInteger`, from an integer parameter.
    Integer,
    /// `IfcLengthMeasure`, from a length parameter, stored in feet.
    Length,
    /// `IfcPositiveLengthMeasure`, from a length parameter, stored in feet.
    PositiveLength,
    /// `IfcThermalTransmittanceMeasure`, from a heat transfer coefficient
    /// parameter, stored in W/(m²·K).
    ThermalTransmittance,
}

/// One IFC4 property set: the entities it applies to, each with the
/// predefined type it is scoped to if any, and its properties of the kinds
/// in [`StandardPropertyKind`].
#[derive(Debug)]
#[non_exhaustive]
pub struct StandardPropertySet {
    /// The set's name.
    pub name: &'static str,
    /// The IFC4 entities it applies to, upper case as rvt-rs writes them,
    /// with their subtypes, and the predefined type a scoped one needs.
    pub applies: &'static [(&'static str, Option<&'static str>)],
    /// Its properties and their kinds.
    pub properties: &'static [(&'static str, StandardPropertyKind)],
    /// The names of its other properties: those of another kind, and those
    /// that are not single values.
    pub other_properties: &'static [&'static str],
}

impl StandardPropertySet {
    /// Whether the set applies to an element written as `ifc_type`, with the
    /// predefined type `predefined_type`: the entity or one of its supertypes
    /// is one the set applies to, with the predefined type the set is scoped
    /// to, if it is.
    pub fn applies_to(&self, ifc_type: &str, predefined_type: Option<&str>) -> bool {
        let mut entity = Some(ifc_type);
        while let Some(current) = entity {
            if self.applies.iter().any(|(applicable, scoped)| {
                *applicable == current
                    && scoped.is_none_or(|scoped| predefined_type == Some(scoped))
            }) {
                return true;
            }
            entity = supertype(current);
        }
        false
    }

    /// Whether IFC4's definition of the set has a property named `property`,
    /// of any kind.
    pub fn defines(&self, property: &str) -> bool {
        self.property_kind(property).is_some() || self.other_properties.contains(&property)
    }

    /// The kind of the set's property `property`, `None` for one not listed.
    pub fn property_kind(&self, property: &str) -> Option<StandardPropertyKind> {
        self.properties
            .iter()
            .find(|(name, _)| *name == property)
            .map(|(_, kind)| *kind)
    }
}

/// IFC4's property sets that apply to an entity, by name.
pub const STANDARD_PROPERTY_SETS: &[StandardPropertySet] = table::SETS;

fn standard_set(name: &str) -> Option<&'static StandardPropertySet> {
    STANDARD_PROPERTY_SETS
        .binary_search_by(|set| set.name.cmp(name))
        .ok()
        .map(|index| &STANDARD_PROPERTY_SETS[index])
}

/// The IFC4 supertype of the entity `ifc_type` (upper case), `None` for a
/// root or an unknown name.
fn supertype(ifc_type: &str) -> Option<&'static str> {
    table::SUPERTYPES
        .binary_search_by(|(entity, _)| (*entity).cmp(ifc_type))
        .ok()
        .map(|index| table::SUPERTYPES[index].1)
}

/// The kind of `property` in the standard set named `set`, `None` for a set
/// or property not listed.
pub fn property_kind(set: &str, property: &str) -> Option<StandardPropertyKind> {
    standard_set(set)?.property_kind(property)
}

/// Whether the standard set named `set` applies to an element written as
/// `ifc_type`, with the predefined type `predefined_type`
/// ([`StandardPropertySet::applies_to`]).
pub fn applies_to(set: &str, ifc_type: &str, predefined_type: Option<&str>) -> bool {
    standard_set(set).is_some_and(|set| set.applies_to(ifc_type, predefined_type))
}
